-doc """
Return the canonical Decaf448 generator from RFC 9496.

Use this point for interoperable generator multiplication.
The base-scalar multiplication operation uses its built-in precomputed table.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_base() -> Result when
    Result :: decaf448_point().
decaf448_base() ->
    ?nif_stub.

-doc """
Multiply the canonical Decaf448 generator by `Scalar`.

Uses the native library's built-in precomputed generator table.
The scalar must already be canonical; otherwise raises `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_base_scalarmul(Scalar) -> Result when
    Scalar :: decaf448_scalar(), Result :: decaf448_point().
decaf448_base_scalarmul(_Scalar) ->
    ?nif_stub.

-doc """
Return the Decaf448 identity element, encoded as 56 zero bytes.

Adding this point leaves the other point unchanged. Multiplication by zero
and multiplication of the identity by any scalar both return the identity.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_identity() -> Result when
    Result :: decaf448_point().
decaf448_identity() ->
    ?nif_stub.

-doc """
Return the canonical encoding of `Left + Right`.

Both operands must be valid point encodings; otherwise raises `badarg`.
Adding a point to its negation returns the identity.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_add(Left, Right) -> Result when
    Left :: decaf448_point(), Right :: decaf448_point(), Result :: decaf448_point().
decaf448_point_add(_Left, _Right) ->
    ?nif_stub.

-doc """
Return `Point + Point` in canonical encoding.

This is equivalent to multiplication by the scalar two.
An invalid point encoding raises `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_double(Point) -> Result when
    Point :: decaf448_point(), Result :: decaf448_point().
decaf448_point_double(_Point) ->
    ?nif_stub.

-doc """
Return `Scalar1 * Point1 + Scalar2 * Point2` in canonical encoding.

Computes the same result as two scalar multiplications followed by addition.
Both points must be valid and both scalars canonical; otherwise raises `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_double_scalarmul(Point1, Scalar1, Point2, Scalar2) -> Result when
    Point1 :: decaf448_point(),
    Scalar1 :: decaf448_scalar(),
    Point2 :: decaf448_point(),
    Scalar2 :: decaf448_scalar(),
    Result :: decaf448_point().
decaf448_point_double_scalarmul(_Point1, _Scalar1, _Point2, _Scalar2) ->
    ?nif_stub.

-doc """
Return whether two encoded points represent the same group element.

Both operands are decoded and validated. Invalid encodings raise `badarg`;
`false` means that two valid points differ.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_eq(Left, Right) -> Result when
    Left :: decaf448_point(), Right :: decaf448_point(), Result :: boolean().
decaf448_point_eq(_Left, _Right) ->
    ?nif_stub.

-doc """
Derive a Decaf448 element from exactly 112 bytes using RFC 9496.

The two halves are mapped separately and their points are added. Uniform
input gives an approximately uniform group element. This operation does
not hash a message: use a protocol-defined, domain-separated hash or XOF
to prepare the input. Wrong-sized binaries and non-binaries raise `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_from_hash(UniformBytes) -> Result when
    UniformBytes :: binary(), Result :: decaf448_point().
decaf448_point_from_hash(_UniformBytes) ->
    ?nif_stub.

-doc """
Apply the upstream single map to exactly 56 bytes.

This is one half of the two-map RFC 9496 derivation. Its output has a
different distribution, so use it only when a protocol requires the single
map. Wrong-sized binaries and non-binaries raise `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_from_hash_nonuniform(Bytes) -> Result when
    Bytes :: binary(), Result :: decaf448_point().
decaf448_point_from_hash_nonuniform(_Bytes) ->
    ?nif_stub.

-doc """
Return whether `Point` is a valid canonical 56-byte Decaf448 encoding.

The identity is valid. Wrong-sized binaries, noncanonical encodings, and
non-binary terms return `false` instead of raising `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_is_valid(Point) -> Result when
    Point :: term(), Result :: boolean().
decaf448_point_is_valid(_Point) ->
    ?nif_stub.

-doc """
Return the additive inverse of `Point` in canonical encoding.

The input point and its negation add to the identity.
An invalid point encoding raises `badarg`.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_negate(Point) -> Result when
    Point :: decaf448_point(), Result :: decaf448_point().
decaf448_point_negate(_Point) ->
    ?nif_stub.

-doc """
Return `Scalar * Point` in canonical encoding.

The point must be valid and the scalar must already be canonical.
Invalid operands raise `badarg`; zero and the identity are accepted.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_scalarmul(Point, Scalar) -> Result when
    Point :: decaf448_point(), Scalar :: decaf448_scalar(), Result :: decaf448_point().
decaf448_point_scalarmul(_Point, _Scalar) ->
    ?nif_stub.

-doc """
Return the canonical encoding of `Left - Right`.

Both operands must be valid point encodings; otherwise raises `badarg`.
Subtracting a point from itself returns the identity.
""".
-doc #{group => "Decaf448"}.
-spec decaf448_point_sub(Left, Right) -> Result when
    Left :: decaf448_point(), Right :: decaf448_point(), Result :: decaf448_point().
decaf448_point_sub(_Left, _Right) ->
    ?nif_stub.

-doc """
Build an immutable native multiplication table for `Point`.

Reuse the table when multiplying the same point by many scalars.
The resource can be shared between processes and is released automatically
