-doc """
Initialize a parallel XOF state.

Accepts the same parameter forms as `xof_init/1` for KT128/KT256,
HopMAC128/HopMAC256, and ParallelHashXOF128/ParallelHashXOF256.
Other algorithms raise `badarg`. KT and HopMAC use 8192-byte leaves;
ParallelHash uses its configured block size. States remain immutable.

```erlang
S0 = libdecaf:parallel_xof_init({parallelhashxof128, 8192}),
S1 = libdecaf:parallel_xof_absorb(S0, <<"invoice-42">>),
{_S2, Output} = libdecaf:parallel_xof_squeeze(S1, 32).
```
""".
-doc #{group => "XOF API"}.
-spec parallel_xof_init(Parameters) -> State when
    Parameters :: parallel_xof_parameters(), State :: parallel_xof_state().
parallel_xof_init(_Parameters) ->
    ?nif_stub.

-doc """
Read output and return `{NextState, Output}`.

The returned state can keep squeezing, but cannot absorb further input.
The input state remains reusable. Output lengths are in bytes.

```erlang
S0 = libdecaf:parallel_xof_absorb(libdecaf:parallel_xof_init(kt128), <<"abc">>),
{S1, First} = libdecaf:parallel_xof_squeeze(S0, 32),
{_S2, Next} = libdecaf:parallel_xof_squeeze(S1, 32),
Combined = <<First/binary, Next/binary>>,
Combined = libdecaf:xof(kt128, <<"abc">>, 64).
```
""".
-doc #{group => "XOF API"}.
-spec parallel_xof_squeeze(State, OutputLength) -> Result when
    State :: parallel_xof_state(), OutputLength :: output_length(), Result :: {parallel_xof_state(), binary()}.
parallel_xof_squeeze(_State, _OutputLength) ->
    ?nif_stub.

