-doc """
Return the canonical Ristretto255 generator from RFC 9496.

Use this point for interoperable generator multiplication.
The base-scalar multiplication operation uses its built-in precomputed table.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_base() -> Result when
    Result :: ristretto255_point().
ristretto255_base() ->
    ?nif_stub.

-doc """
Multiply the canonical Ristretto255 generator by `Scalar`.

Uses the native library's built-in precomputed generator table.
The scalar must already be canonical; otherwise raises `badarg`.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_base_scalarmul(Scalar) -> Result when
    Scalar :: ristretto255_scalar(), Result :: ristretto255_point().
ristretto255_base_scalarmul(_Scalar) ->
    ?nif_stub.

-doc """
Return the Ristretto255 identity element, encoded as 32 zero bytes.

Adding this point leaves the other point unchanged. Multiplication by zero
and multiplication of the identity by any scalar both return the identity.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_identity() -> Result when
    Result :: ristretto255_point().
ristretto255_identity() ->
    ?nif_stub.

-doc """
Return the canonical encoding of `Left + Right`.

Both operands must be valid point encodings; otherwise raises `badarg`.
Adding a point to its negation returns the identity.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_point_add(Left, Right) -> Result when
    Left :: ristretto255_point(), Right :: ristretto255_point(), Result :: ristretto255_point().
ristretto255_point_add(_Left, _Right) ->
    ?nif_stub.

-doc """
Return `Point + Point` in canonical encoding.

This is equivalent to multiplication by the scalar two.
An invalid point encoding raises `badarg`.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_point_double(Point) -> Result when
    Point :: ristretto255_point(), Result :: ristretto255_point().
ristretto255_point_double(_Point) ->
    ?nif_stub.

-doc """
Return `Scalar1 * Point1 + Scalar2 * Point2` in canonical encoding.

Computes the same result as two scalar multiplications followed by addition.
Both points must be valid and both scalars canonical; otherwise raises `badarg`.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_point_double_scalarmul(Point1, Scalar1, Point2, Scalar2) -> Result when
    Point1 :: ristretto255_point(),
    Scalar1 :: ristretto255_scalar(),
    Point2 :: ristretto255_point(),
    Scalar2 :: ristretto255_scalar(),
    Result :: ristretto255_point().
ristretto255_point_double_scalarmul(_Point1, _Scalar1, _Point2, _Scalar2) ->
    ?nif_stub.

-doc """
Return whether two encoded points represent the same group element.

Both operands are decoded and validated. Invalid encodings raise `badarg`;
`false` means that two valid points differ.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_point_eq(Left, Right) -> Result when
    Left :: ristretto255_point(), Right :: ristretto255_point(), Result :: boolean().
ristretto255_point_eq(_Left, _Right) ->
    ?nif_stub.

-doc """
Derive a Ristretto255 element from exactly 64 bytes using RFC 9496.

The two halves are mapped separately and their points are added. Uniform
input gives an approximately uniform group element. This operation does
not hash a message: use a protocol-defined, domain-separated hash or XOF
to prepare the input. Wrong-sized binaries and non-binaries raise `badarg`.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_point_from_hash(UniformBytes) -> Result when
    UniformBytes :: binary(), Result :: ristretto255_point().
ristretto255_point_from_hash(_UniformBytes) ->
    ?nif_stub.

-doc """
Apply the upstream single map to exactly 32 bytes.

This is one half of the two-map RFC 9496 derivation. Its output has a
different distribution, so use it only when a protocol requires the single
map. Wrong-sized binaries and non-binaries raise `badarg`.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_point_from_hash_nonuniform(Bytes) -> Result when
    Bytes :: binary(), Result :: ristretto255_point().
ristretto255_point_from_hash_nonuniform(_Bytes) ->
    ?nif_stub.

-doc """
Return whether `Point` is a valid canonical 32-byte Ristretto255 encoding.

The identity is valid. Wrong-sized binaries, noncanonical encodings, and
non-binary terms return `false` instead of raising `badarg`.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_point_is_valid(Point) -> Result when
    Point :: term(), Result :: boolean().
ristretto255_point_is_valid(_Point) ->
    ?nif_stub.

-doc """
Return the additive inverse of `Point` in canonical encoding.

The input point and its negation add to the identity.
An invalid point encoding raises `badarg`.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_point_negate(Point) -> Result when
    Point :: ristretto255_point(), Result :: ristretto255_point().
ristretto255_point_negate(_Point) ->
    ?nif_stub.

-doc """
Return `Scalar * Point` in canonical encoding.

The point must be valid and the scalar must already be canonical.
Invalid operands raise `badarg`; zero and the identity are accepted.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_point_scalarmul(Point, Scalar) -> Result when
    Point :: ristretto255_point(), Scalar :: ristretto255_scalar(), Result :: ristretto255_point().
ristretto255_point_scalarmul(_Point, _Scalar) ->
    ?nif_stub.

-doc """
Return the canonical encoding of `Left - Right`.

Both operands must be valid point encodings; otherwise raises `badarg`.
Subtracting a point from itself returns the identity.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_point_sub(Left, Right) -> Result when
    Left :: ristretto255_point(), Right :: ristretto255_point(), Result :: ristretto255_point().
ristretto255_point_sub(_Left, _Right) ->
    ?nif_stub.

-doc """
Build an immutable native multiplication table for `Point`.

Reuse the table when multiplying the same point by many scalars.
The resource can be shared between processes and is released automatically
when no references remain. It is specific to Ristretto255; invalid points raise `badarg`.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_precompute(Point) -> Result when
    Point :: ristretto255_point(), Result :: ristretto255_precomputed().
ristretto255_precompute(_Point) ->
    ?nif_stub.

-doc """
Multiply the point stored in `Precomputed` by `Scalar`.

The result matches ordinary point-scalar multiplication; the table is unchanged.
A resource from another group, a non-table term, or a noncanonical Ristretto255
scalar raises `badarg`.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_precomputed_scalarmul(Precomputed, Scalar) -> Result when
    Precomputed :: ristretto255_precomputed(), Scalar :: ristretto255_scalar(), Result :: ristretto255_point().
ristretto255_precomputed_scalarmul(_Precomputed, _Scalar) ->
    ?nif_stub.

-doc """
Return `(Left + Right) mod l`, where `l` is the group order.

Both operands must already be canonical scalars; otherwise raises `badarg`.
The result is canonically encoded.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_scalar_add(Left, Right) -> Result when
    Left :: ristretto255_scalar(), Right :: ristretto255_scalar(), Result :: ristretto255_scalar().
ristretto255_scalar_add(_Left, _Right) ->
    ?nif_stub.

-doc """
Divide `Scalar` by two modulo the group order.

This is multiplication by the modular inverse of two, rather than integer
division. Adding the result to itself recovers the input, including for odd
scalars. A noncanonical scalar raises `badarg`.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_scalar_halve(Scalar) -> Result when
    Scalar :: ristretto255_scalar(), Result :: ristretto255_scalar().
ristretto255_scalar_halve(_Scalar) ->
    ?nif_stub.

-doc """
Return the multiplicative inverse of `Scalar` modulo the group order.

Multiplying a nonzero scalar by its inverse gives the canonical scalar one.
Zero has no inverse and returns `error`. Noncanonical scalars raise `badarg`.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_scalar_invert(Scalar) -> Result when
    Scalar :: ristretto255_scalar(), Result :: ristretto255_scalar() | error.
ristretto255_scalar_invert(_Scalar) ->
    ?nif_stub.

-doc """
Return whether `Scalar` is a canonical 32-byte little-endian scalar.

Its integer value must be smaller than the group order; zero is accepted.
Wrong-sized binaries, out-of-range values, and non-binaries return `false`.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_scalar_is_canonical(Scalar) -> Result when
    Scalar :: term(), Result :: boolean().
ristretto255_scalar_is_canonical(_Scalar) ->
    ?nif_stub.

-doc """
Return `(Left * Right) mod l`, where `l` is the group order.

Both operands must already be canonical scalars; otherwise raises `badarg`.
The result is canonically encoded.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_scalar_mul(Left, Right) -> Result when
    Left :: ristretto255_scalar(), Right :: ristretto255_scalar(), Result :: ristretto255_scalar().
ristretto255_scalar_mul(_Left, _Right) ->
    ?nif_stub.

-doc """
Return `-Scalar mod l`, where `l` is the group order.

The result adds to the input to give zero; zero is its own negation.
A noncanonical scalar raises `badarg`.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_scalar_negate(Scalar) -> Result when
    Scalar :: ristretto255_scalar(), Result :: ristretto255_scalar().
ristretto255_scalar_negate(_Scalar) ->
    ?nif_stub.

-doc """
Reduce an arbitrary-length unsigned little-endian integer modulo the group order.

Returns a canonical 32-byte scalar. Leading zero bytes at the
most-significant end are allowed, and the empty binary reduces to zero.
This operation does not hash or clamp its input. Non-binaries raise `badarg`.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_scalar_reduce(Bytes) -> Result when
    Bytes :: binary(), Result :: ristretto255_scalar().
ristretto255_scalar_reduce(_Bytes) ->
    ?nif_stub.

-doc """
Return `(Left - Right) mod l`, where `l` is the group order.

Both operands must already be canonical scalars; otherwise raises `badarg`.
A negative difference wraps modulo `l` and the result is canonically encoded.
""".
-doc #{group => "Ristretto255"}.
-spec ristretto255_scalar_sub(Left, Right) -> Result when
    Left :: ristretto255_scalar(), Right :: ristretto255_scalar(), Result :: ristretto255_scalar().
ristretto255_scalar_sub(_Left, _Right) ->
    ?nif_stub.

